package com.ecommerce.servlet;
import com.ecommerce.exception.AppException; import com.ecommerce.model.*; import com.ecommerce.service.*; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*;
@WebServlet("/checkout") public class CheckoutServlet extends HttpServlet { private final OrderService service=new OrderService(); private final OrderProcessingService processor=new OrderProcessingService(); protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=(User)req.getSession().getAttribute("user");if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;}@SuppressWarnings("unchecked") Map<Integer,CartItem> cart=(Map<Integer,CartItem>)req.getSession().getAttribute("cart");if(cart==null)cart=new LinkedHashMap<>();int orderId=service.checkout(u.getId(),cart);req.getSession().removeAttribute("cart");String msg=processor.processAsync(orderId).get();req.setAttribute("message",msg);req.getRequestDispatcher("/WEB-INF/views/success.jsp").forward(req,resp);}catch(AppException e){req.setAttribute("error",e.getMessage());req.getRequestDispatcher("/WEB-INF/views/cart.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}} @Override public void destroy(){processor.close();} }
